<?php
require_once __DIR__ . '/../config/database.php';require_admin();$pdo=db();$stats=[];$stats['reportes']=(int)$pdo->query('SELECT COUNT(*) FROM reportes')->fetchColumn();$stats['pendientes']=(int)$pdo->query("SELECT COUNT(*) FROM reportes r JOIN estados e ON e.id=r.id_estado WHERE e.nombre='Pendiente'")->fetchColumn();$stats['en_proceso']=(int)$pdo->query("SELECT COUNT(*) FROM reportes r JOIN estados e ON e.id=r.id_estado WHERE e.nombre IN ('En revisión','En reparación')")->fetchColumn();$stats['solucionados']=(int)$pdo->query("SELECT COUNT(*) FROM reportes r JOIN estados e ON e.id=r.id_estado WHERE e.nombre='Solucionado'")->fetchColumn();$stats['usuarios']=(int)$pdo->query('SELECT COUNT(*) FROM usuarios WHERE activo=1')->fetchColumn();json_response(['ok'=>true,'stats'=>$stats]);
